import type { ArrayFrame } from "@bsc/algorithms/trace";

/** Insertion sort as a step-yielding generator (generator-as-source, #3171): mutates `a` in place and
 *  yields one ArrayFrame per step. The plain `sort` drains it to order the array; the Algorithms
 *  Visualization pane animates the same yields - compare/swap verbs bound to <ArrayView>'s animations. */
export function* sortSteps(a: number[]): Generator<ArrayFrame> {
  yield { structure: "array", data: [...a] };
  for (let i = 1; i < a.length; i++) {
    let j = i;
    while (j > 0) {
      yield { structure: "array", data: [...a], ops: [{ op: "compare", at: [j - 1, j] }], cursors: { i, j } };
      if (a[j - 1] <= a[j]) break;
      [a[j - 1], a[j]] = [a[j], a[j - 1]];
      yield { structure: "array", data: [...a], ops: [{ op: "swap", at: [j - 1, j] }], cursors: { i, j } };
      j--;
    }
  }
  yield { structure: "array", data: [...a], ops: a.map((_, k) => ({ op: "mark", at: k, as: "sorted" })) };
}

/** Sort ascending by draining the generator (one source of truth). Pure - never mutates the input. */
export const sort = (input: number[]): number[] => {
  const a = [...input];
  const steps = sortSteps(a);
  while (!steps.next().done) { /* drain - sortSteps mutates `a` in place */ }
  return a;
};

export function transpose(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) [a[i][j], a[j][i]] = [a[j][i], a[i][j]];
  return a;
}

export function rotate90(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let l = 0; l < Math.floor(n / 2); l++) {
    const f = l, e = n - 1 - l;
    for (let i = f; i < e; i++) {
      const o = i - f, t = a[f][i];
      a[f][i] = a[e - o][f];
      a[e - o][f] = a[e][e - o];
      a[e][e - o] = a[i][e];
      a[i][e] = t;
    }
  }
  return a;
}

export function reflect(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a[0].length;
  for (const r of a)
    for (let c = 0; c < Math.floor(n / 2); c++) [r[c], r[n - 1 - c]] = [r[n - 1 - c], r[c]];
  return a;
}

/** Wh per 1k tokens by model tier — directional coefficients, not metered readings. */
const WH_PER_1K: Record<"large" | "medium" | "small" | "local", { in: number; out: number }> = {
  large: { in: 0.05, out: 0.9 },
  medium: { in: 0.03, out: 0.4 },
  small: { in: 0.01, out: 0.15 },
  local: { in: 0, out: 0 },
};

/** Classify a model name into an energy tier by name pattern; unknown hosted models fall to medium. */
function tier(model: string): keyof typeof WH_PER_1K {
  const m = model.toLowerCase();
  if (/local|ollama|llama|mistral|qwen|deepseek|phi/.test(m)) return "local";
  if (/opus|ultra|gpt-4(?!o)|gpt4(?!o)/.test(m)) return "large";
  if (/haiku|mini|flash|nano|small|lite/.test(m)) return "small";
  return "medium";
}

/** Estimated Wh for an input/output token split at the model's tier. Directional, not metered. */
export function estimateEnergyWh(model: string, inputTokens: number, outputTokens: number): number {
  const k = WH_PER_1K[tier(model)];
  return (inputTokens / 1000) * k.in + (outputTokens / 1000) * k.out;
}

/**
 * Resolve ONE state from N independent signal sources, by a declared precedence order.
 *
 * The everyday shape of "which status is this thing in?" when several sources can each claim it at
 * once and the answer must be single-valued and stable. The ordering is DATA, not control flow: the
 * common alternative is a chain of `if` returns, where the precedence exists only in the sequence of
 * the statements and cannot be read, tested, or changed without editing the branch order.
 *
 * The first source (in order) that claims the subject wins. Sources are consulted lazily, so an
 * expensive predicate placed low in the order is not paid for when something above it already matched.
 *
 * Harvested from the Fleet page's per-worker status (#3462/#3465), where coordination signals
 * (asking / waiting / blocked) outrank the raw run/idle sample, which in turn outranks a parked
 * maintenance worker — an order chosen so a worker that needs a human is never hidden behind a
 * mechanical "running".
 */

/** One candidate state and the test that claims it. `when` is only called until one matches. */
export interface PrecedenceRule<TSubject, TState> {
  /** The state this rule resolves to when it claims the subject. */
  state: TState;
  /** Does this source claim the subject? */
  when: (subject: TSubject) => boolean;
}

/**
 * The first rule (in order) whose `when` claims `subject`, else `fallback`.
 *
 * Total by construction — a `fallback` is required rather than optional, so there is no "resolved to
 * nothing" case for a caller to forget. That matters here: the states this resolves are rendered, and
 * an undefined status is a blank badge rather than a visible problem.
 */
export function resolveByPrecedence<TSubject, TState>(
  subject: TSubject,
  rules: ReadonlyArray<PrecedenceRule<TSubject, TState>>,
  fallback: TState,
): TState {
  for (const rule of rules) {
    if (rule.when(subject)) return rule.state;
  }
  return fallback;
}

/**
 * The rules that claimed `subject`, in precedence order — every match, not just the winner.
 *
 * The winner alone answers "what is it?"; this answers "what else was true?", which is what an
 * explanation needs. A worker resolving to `running` while also matching `maintenance` is a different
 * situation from one that matches `running` only, and a UI that can say so is more use than one that
 * silently discards the runners-up.
 */
export function matchingPrecedence<TSubject, TState>(
  subject: TSubject,
  rules: ReadonlyArray<PrecedenceRule<TSubject, TState>>,
): TState[] {
  return rules.filter((r) => r.when(subject)).map((r) => r.state);
}

/**
 * Bucket K timestamp streams into per-day counts over a rolling N-day window, aligned to one label
 * axis — the shape every "activity over the last N days" chart needs.
 *
 * Two properties are the whole point, and both are easy to get wrong by hand:
 *
 * 1. **Empty days are present.** The window is built first and every stream is tallied INTO it, so a
 *    day with no events is a `0`, not a missing entry. Deriving labels from the data instead (the
 *    obvious shortcut) silently compresses quiet days out of the axis, which makes a gap look like a
 *    dip and misstates the trend.
 * 2. **The series are aligned.** Every returned series has exactly `days` entries in the same order as
 *    `labels`, so index `i` means the same day in all of them. A chart layering two series cannot check
 *    this and will happily plot them against each other misaligned.
 *
 * Days are UTC — a rolling window whose bucket boundaries move with the viewer's timezone would make
 * the same data tell two stories. Timestamps are ISO-8601; anything unparseable or outside the window
 * is dropped rather than clamped, because a bad timestamp landing on an edge day is a fabricated event.
 *
 * Harvested from the Fleet page's throughput panel (#3462/#3465).
 */

/** The day axis: display labels and the `YYYY-MM-DD` keys they bucket by, oldest → newest. */
export interface DayWindow {
  labels: string[];
  keys: string[];
}

/** The aligned result: one label axis and one equal-length numeric series per input stream. */
export interface WindowedTally<TName extends string> {
  labels: string[];
  series: Record<TName, number[]>;
}

/**
 * The last `days` UTC days ending at `now` (inclusive), oldest first.
 *
 * `days <= 0` yields an empty window rather than throwing — a caller asking for no window gets no
 * window, and every tally over it is correctly empty.
 */
export function dayWindow(days: number, now: Date): DayWindow {
  const labels: string[] = [];
  const keys: string[] = [];
  for (let i = Math.max(0, Math.floor(days)) - 1; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 86_400_000);
    labels.push(`${d.getUTCMonth() + 1}/${d.getUTCDate()}`);
    keys.push(d.toISOString().slice(0, 10));
  }
  return { labels, keys };
}

/**
 * Count the timestamps falling on each day of `win`, in window order.
 *
 * Null/undefined/unparseable entries are skipped — these streams come from APIs where "not merged
 * yet" is a null timestamp, so filtering at the call site would be required of every caller.
 */
export function tallyByDay(win: DayWindow, timestamps: ReadonlyArray<string | null | undefined>): number[] {
  const index = new Map(win.keys.map((k, i) => [k, i]));
  const out = new Array<number>(win.keys.length).fill(0);
  for (const ts of timestamps) {
    if (!ts) continue;
    const at = index.get(ts.slice(0, 10));
    if (at !== undefined) out[at] += 1;
  }
  return out;
}

/**
 * Tally several named streams over ONE window, so the result is aligned by construction.
 *
 * Preferred over calling {@link tallyByDay} per stream: sharing the window is what guarantees the
 * series line up, and doing it here removes the caller's opportunity to build two windows a
 * millisecond apart and land the boundary event in different buckets.
 */
export function windowedTally<TName extends string>(
  streams: Record<TName, ReadonlyArray<string | null | undefined>>,
  days: number,
  now: Date,
): WindowedTally<TName> {
  const win = dayWindow(days, now);
  const series = {} as Record<TName, number[]>;
  for (const name of Object.keys(streams) as TName[]) {
    series[name] = tallyByDay(win, streams[name]);
  }
  return { labels: win.labels, series };
}

/**
 * Merge K differently-shaped event streams into ONE recent-first feed, with a distinguished class
 * pinned ABOVE the time sort, plus a count per kind.
 *
 * The shape behind every "activity" / "what needs attention" panel that draws from several sources at
 * once (errors, warnings, denials, …). Three things it gets right that the hand-written version gets
 * wrong under maintenance:
 *
 * 1. **Heterogeneous in, homogeneous out.** Each stream has its OWN shape and its own projection to a
 *    common item; the merge never sees the source shapes. Adding a stream is adding a `(source,
 *    project)` pair, not editing a growing sort.
 * 2. **A pinned class outranks recency.** Some items are LIVE ("this is happening now") and must sit
 *    at the top regardless of timestamp — a currently-stalled worker above yesterday's resolved error.
 *    Modelled as a real flag (`pinned`), not the sentinel `sortKey: Infinity` the original used, which
 *    silently breaks the moment a second pinned item needs ordering among its peers.
 * 3. **Counts come from the merged feed, not recomputed.** One pass, so the badge can never disagree
 *    with the list it summarises.
 *
 * Sort is STABLE within a rank: pinned-vs-unpinned first, then `sortKey` descending, ties keeping
 * input order — so equal-timestamp items don't reshuffle between renders. Harvested from the Fleet
 * page's health panel (#3462/#3465).
 */

/** One normalized feed entry. `kind` is the caller's classification (counted); `pinned` lifts it above
 *  the time sort; `sortKey` orders the rest (a timestamp, descending = newest first). */
export interface FeedItem<TKind extends string> {
  kind: TKind;
  pinned: boolean;
  sortKey: number;
}

/** One input stream: its raw items plus how to project each to a {@link FeedItem}. Generic over the
 *  source shape AND the extra payload `P` the projection carries through (label, detail, …). */
export interface FeedStream<TKind extends string, P> {
  items: readonly unknown[];
  project: (raw: unknown) => (FeedItem<TKind> & P) | null;
}

/** Build one typed stream — a small helper so the source type is inferred rather than cast at the
 *  call site (each stream keeps its own element type until `project` normalizes it). */
export function feedStream<TRaw, TKind extends string, P>(
  items: readonly TRaw[],
  project: (raw: TRaw) => (FeedItem<TKind> & P) | null,
): FeedStream<TKind, P> {
  return { items, project: (raw) => project(raw as TRaw) };
}

/** The merged result: the ordered feed and a count per kind (every kind in `kinds` present, zeros
 *  included, so a caller can render a fixed set of badges without guarding for missing keys). */
export interface MergedFeed<TKind extends string, P> {
  items: Array<FeedItem<TKind> & P>;
  counts: Record<TKind, number>;
  total: number;
  hasItems: boolean;
}

/**
 * Merge the streams into one ordered feed with per-kind counts.
 *
 * `kinds` is the closed set of classifications, passed IN so `counts` has a zero for every one — the
 * feed alone can only count kinds that occurred, and a badge row that appears and disappears with the
 * data is worse than one that reads `0`.
 *
 * A stream's `project` returning null drops that raw item (a "done" verdict is not an error), so
 * filtering is part of the projection rather than a separate pass the caller has to remember.
 */
export function mergeFeeds<TKind extends string, P>(
  streams: ReadonlyArray<FeedStream<TKind, P>>,
  kinds: readonly TKind[],
): MergedFeed<TKind, P> {
  const items: Array<FeedItem<TKind> & P> = [];
  for (const stream of streams) {
    for (const raw of stream.items) {
      const item = stream.project(raw);
      if (item) items.push(item);
    }
  }
  // Stable: pinned first, then newest first, ties keeping insertion order (Array.sort is stable).
  items.sort((a, b) => (a.pinned === b.pinned ? b.sortKey - a.sortKey : a.pinned ? -1 : 1));

  const counts = Object.fromEntries(kinds.map((k) => [k, 0])) as Record<TKind, number>;
  for (const it of items) counts[it.kind] += 1;

  return { items, counts, total: items.length, hasItems: items.length > 0 };
}

/**
 * Sort items by a DECLARED priority ranking of a category — an order that is deliberately NOT the
 * category's natural or alphabetical one.
 *
 * The everyday case is an "attention queue": items fall into a few states and the useful order is by
 * urgency, which no property of the state gives you. Written by hand it becomes a bare comparator with
 * the ranking buried in a chain of ternaries (`s === "blocked" ? 0 : s === "running" ? 1 : …`) — the
 * priority is real domain knowledge but exists only as magic numbers inside a sort, where it cannot be
 * read as a list, reused, or reordered without recounting.
 *
 * Here the ranking is DATA: an array, first = highest priority. That array is the decision; the sort
 * is mechanical. A category not in the ranking sorts AFTER every ranked one (rather than silently
 * becoming rank 0 and jumping the queue) — an unranked value is "no stated priority", not "top
 * priority". The sort is STABLE, so items of equal rank keep their input order.
 *
 * Harvested from the Fleet page's merge queue (#3462/#3465).
 */

/**
 * A stable copy of `items` ordered by the priority of each item's category.
 *
 * `ranking[0]` is highest priority. An item whose category is not in `ranking` sorts after every
 * ranked item, in input order among its unranked peers.
 */
export function orderByRank<T, R>(
  items: readonly T[],
  categoryOf: (item: T) => R,
  ranking: readonly R[],
): T[] {
  const rankOf = new Map<R, number>(ranking.map((r, i) => [r, i]));
  // Unranked → after everything ranked. `ranking.length` sits past the last real rank.
  const rank = (item: T) => rankOf.get(categoryOf(item)) ?? ranking.length;
  // Decorate-sort-undecorate keeps it stable AND calls `categoryOf` once per item rather than O(n log n)
  // times — the naive `.sort((a,b) => rank(a) - rank(b))` re-derives the category on every comparison.
  return items
    .map((item, i) => ({ item, i, r: rank(item) }))
    .sort((a, b) => a.r - b.r || a.i - b.i)
    .map((d) => d.item);
}

/**
 * Group rows by a key and total a set of numeric fields — per group AND overall — in ONE pass.
 *
 * The back half of every "spend by X" / "usage by Y" rollup: you have a flat list of rows, each with
 * several numbers, and you want both the grand totals and the same totals broken down by some
 * secondary key. Written by hand it is three separate reductions plus a `Map` accumulator, and the
 * usual bug is the group subtotals and the grand total drifting apart because they were summed
 * independently — here they come from the same traversal, so they cannot disagree.
 *
 * The fields to sum are DATA: a record of named numeric accessors. Adding a tracked metric is adding
 * one entry, not editing three reducers. Every field is totalled at both levels; a caller wanting only
 * some grouped just reads the ones it needs.
 *
 * Group order is FIRST-SEEN (insertion order of the backing Map), so the result is deterministic for a
 * given input and a caller that wants a different order sorts the returned groups itself — this does
 * not bake a sort in, because "by first appearance" is the one order that needs no opinion.
 *
 * Harvested from the Fleet page's cost panel (#3462/#3465), where it rolls per-worker token usage up
 * to fleet totals and a by-model breakdown.
 */

/** The totals for one field set — the same keys as the `fields` record, each a summed number. */
export type FieldTotals<F extends string> = Record<F, number>;

/** One group: its key, how many rows fell into it, and the per-field totals for those rows. */
export interface Group<K, F extends string> {
  key: K;
  count: number;
  totals: FieldTotals<F>;
}

/** The rollup: the grand totals over every row, and the per-group breakdown (first-seen order). */
export interface GroupTotals<K, F extends string> {
  totals: FieldTotals<F>;
  count: number;
  groups: Array<Group<K, F>>;
}

/**
 * Total `fields` over `rows`, grouped by `keyOf`.
 *
 * @param rows   the flat input.
 * @param keyOf  the grouping key for a row (the secondary axis — e.g. model name).
 * @param fields named numeric accessors; each is summed at both the group and grand-total level.
 */
export function groupTotals<T, K, F extends string>(
  rows: readonly T[],
  keyOf: (row: T) => K,
  fields: Record<F, (row: T) => number>,
): GroupTotals<K, F> {
  const names = Object.keys(fields) as F[];
  const zero = (): FieldTotals<F> => Object.fromEntries(names.map((n) => [n, 0])) as FieldTotals<F>;

  const grand = zero();
  const groups = new Map<K, Group<K, F>>();

  for (const row of rows) {
    const key = keyOf(row);
    let group = groups.get(key);
    if (!group) {
      group = { key, count: 0, totals: zero() };
      groups.set(key, group);
    }
    group.count += 1;
    for (const name of names) {
      const v = fields[name](row);
      group.totals[name] += v;
      grand[name] += v;
    }
  }

  return { totals: grand, count: rows.length, groups: [...groups.values()] };
}
